/**
 * js/i18n/pt-BR.js — Diccionario español → portugués de Brasil.
 * ─────────────────────────────────────────────────────────────────────────────
 * Lo carga js/i18n.js solo cuando el idioma elegido es pt-BR. La clave es el
 * texto en español tal como lo pinta el módulo (espacios colapsados); {0}, {1}…
 * son huecos que se rellenan con lo que el módulo concatenó (y que a su vez se
 * traducen si están aquí). Glosario «un nombre por concepto» en CLAUDE.md
 * (sección Idioma). Al agregar un texto nuevo en español a la UI, agrégalo
 * también aquí.
 */
