  "Starter cuesta 497 USD al mes. Si con eso consigues una sola reunión calificada y cierras un ticket de 5,000 USD, tu costo de adquisición fue 497 USD por 5,000 USD de ingreso: más de 10 veces lo invertido. Todo lo que venga después de esa primera reunión es margen.": "O Starter custa US$ 497 por mês. Se com isso você conseguir uma única reunião qualificada e fechar um ticket de US$ 5.000, seu custo de aquisição foi de US$ 497 para US$ 5.000 de receita: mais de 10 vezes o investimento. Tudo o que vier depois dessa primeira reunião é margem.",
  "Ajusta los números a tu negocio. Si tu ticket es recurrente, cuenta los meses; si tu equipo cierra más de una reunión al mes, súmalas. La inversión no cambia.": "Ajuste os números ao seu negócio. Se o seu ticket é recorrente, conte os meses; se a sua equipe fecha mais de uma reunião por mês, some todas. O investimento não muda.",
