  "Estamos preparando tu análisis de mercado en el Intelligence Hub. Cuando esté listo, revísalo y confírmalo: el Radar diseña su plan sobre él.": "Estamos preparando sua análise de mercado no Intelligence Hub. Quando estiver pronta, revise e confirme: o Radar monta o plano dele com base nela.",
