  "Aquí se define en qué países investigar, a qué industrias y cargos apuntar y con qué voz escribir. Sin eso, el research saldría sobre el mercado equivocado.": "Aqui você define em quais países pesquisar, quais setores e cargos mirar e com que voz escrever. Sem isso, a pesquisa seria feita sobre o mercado errado.",
