  "El Radar necesita saber qué buscar. A partir del contexto de tu empresa y de lo que dice tu Intelligence Hub, la IA diseña un plan con varios detectores (noticias, vacantes, tecnografía, sondeo de sitios web, financiamiento, cambios de liderazgo, licitaciones, presencia local, visitantes web). Tú lo apruebas y desde ahí corre solo.": "O Radar precisa saber o que procurar. A partir do contexto da sua empresa e do que diz o seu Intelligence Hub, a IA monta um plano com vários detectores (notícias, vagas, tecnografia, varredura de sites, captação de investimento, mudanças de liderança, licitações, presença local, visitantes do site). Você aprova e, a partir daí, ele roda sozinho.",
