  "Más de 70 señales listas que van más allá de Apollo: leemos el sitio y el DNS de cada empresa (Meta Business Manager, WhatsApp sin plataforma o con un bot rígido, tiendas en Mercado Libre y Amazon, pasarelas de pago, email marketing, DMARC…) y buscamos su huella pública en internet. Se agregan con un clic, sin costo extra de IA.": "Mais de 70 sinais prontos que vão além do Apollo: lemos o site e o DNS de cada empresa (Meta Business Manager, WhatsApp sem plataforma ou com um bot engessado, lojas no Mercado Livre e na Amazon, gateways de pagamento, e-mail marketing, DMARC…) e buscamos a pegada pública dela na internet. Você adiciona com um clique, sem custo extra de IA.",
  "{0} señales": "{0} sinais",
  "Cargando la biblioteca…": "Carregando a biblioteca…",
  "Busca por lo que vendes: WhatsApp, Meta Ads, marketplaces, pagos, ciberseguridad…": "Busque pelo que você vende: WhatsApp, Meta Ads, marketplaces, pagamentos, cibersegurança…",
  "Ninguna señal coincide. Prueba otra palabra o agrega un detector propio describiéndolo abajo.": "Nenhum sinal corresponde. Tente outra palavra ou adicione um detector próprio descrevendo-o abaixo.",
  "Diseña tu plan de señales": "Monte seu plano de sinais",
  "La IA lee el contexto de tu empresa (qué vendes, a quién, en qué países) y lo que tu Intelligence Hub dice del mercado, y propone entre 5 y 10 detectores: cada uno una forma distinta de encontrar empresas que te necesitan ahora. Después los ajustas, los activas y corren solos.": "A IA lê o contexto da sua empresa (o que você vende, para quem, em quais países) e o que o seu Intelligence Hub diz sobre o mercado, e propõe de 5 a 10 detectores: cada um é uma forma diferente de encontrar empresas que precisam de você agora. Depois você ajusta, ativa e eles rodam sozinhos.",
  "Generar plan con IA": "Gerar plano com IA",
