  "No creamos plantillas por ti: después de conectar creas las tuyas en la pestaña de WhatsApp y eliges una en cada paso de tus campañas. Con estos datos te sugerimos el saludo: \"Hola {{name}}, te saluda {0}. Qué tal todo?\"": "Não criamos modelos por você: depois de conectar, você cria os seus na aba do WhatsApp e escolhe um em cada etapa das suas campanhas. Com estes dados, sugerimos a saudação: \"Olá {{name}}, aqui é {0}. Tudo bem?\"",
