  "mensaje de LinkedIn": "mensagem de LinkedIn",
  "conexión de LinkedIn": "conexão de LinkedIn",
  "Esta campaña todavía no existe en Dripify. Créala allá con el mismo nombre (Editar / vincular te da cada texto para copiar): el paso espera y se vincula solo en cuanto exista.": "Esta campanha ainda não existe no Dripify. Crie-a lá com o mesmo nome (Editar / vincular mostra cada texto para copiar): a etapa aguarda e é vinculada sozinha assim que ela existir.",
  "Este paso sube al lead a una campaña de Dripify que SOLO manda un mensaje, y solo si ya aceptó tu conexión. El texto se escribe en Dripify (su API no acepta texto por lead). Sale desde tu cuenta de LinkedIn al ritmo que decide Dripify.": "Esta etapa envia o lead para uma campanha do Dripify que SÓ manda uma mensagem, e só se ele já tiver aceitado sua conexão. O texto é escrito no Dripify (a API dele não aceita texto por lead). Sai da sua conta do LinkedIn no ritmo que o Dripify define.",
  "Este paso sube al lead a una campaña de Dripify que SOLO manda la solicitud de conexión. Sale desde tu cuenta de LinkedIn al ritmo que decide Dripify.": "Esta etapa envia o lead para uma campanha do Dripify que SÓ manda a solicitação de conexão. Sai da sua conta do LinkedIn no ritmo que o Dripify define.",
  "Importante: la campaña que elijas en Dripify tiene que tener un único paso. Si trae su propia secuencia de mensajes, Dripify la sigue por su cuenta y seguirá escribiendo aunque el lead ya te haya respondido por WhatsApp o por email — Predictable no puede detener lo que corre allá. Por eso la conexión y cada mensaje son pasos separados aquí.": "Importante: a campanha que você escolher no Dripify precisa ter uma única etapa. Se ela tiver uma sequência própria de mensagens, o Dripify a executa por conta própria e continua escrevendo mesmo que o lead já tenha respondido por WhatsApp ou por e-mail — o Predictable não consegue interromper o que roda lá. Por isso a conexão e cada mensagem são etapas separadas aqui.",
  "Contenido": "Conteúdo",
  "Recomendado: un mensaje distinto por lead": "Recomendado: uma mensagem diferente por lead",
  "Mi texto": "Meu texto",
  "El mismo texto con variables": "O mesmo texto com variáveis",
  "Plantilla de WhatsApp": "Modelo de WhatsApp",
  "Aprobada por Meta: abre conversación": "Aprovado pela Meta: abre conversa",
  "Ángulo": "Ângulo",
  "Instrucciones para la IA en este paso (opcional). Ej.: menciona el caso de un cliente de retail; no hables de precio.": "Instruções para a IA nesta etapa (opcional). Ex.: mencione o caso de um cliente do varejo; não fale de preço.",
  "Instrucciones": "Instruções",
  "WhatsApp solo permite texto libre dentro de las 24 h siguientes a un mensaje del lead. Si no hay conversación abierta, este paso se omite; para abrir conversación usa una plantilla de WhatsApp.": "O WhatsApp só permite texto livre nas 24 h seguintes a uma mensagem do lead. Se não houver conversa aberta, esta etapa é ignorada; para abrir uma conversa, use um modelo de WhatsApp.",
  "La IA escribe el mensaje de cada lead 24 h antes del envío, con el ángulo y las instrucciones de ESTE paso, tu contexto de empresa, el brief y lo que ya se le envió. Cuesta 2 créditos por mensaje.": "A IA escreve a mensagem de cada lead 24 h antes do envio, com o ângulo e as instruções DESTA etapa, o contexto da sua empresa, o brief e o que já foi enviado a ele. Custa 2 créditos por mensagem.",
  "Asunto": "Assunto",
  "Hola {{nombre}}, vi que lideras {{cargo}} en {{empresa}}…": "Olá, {{nombre}}, vi que você lidera {{cargo}} na {{empresa}}…",
  "Texto del mensaje": "Texto da mensagem",
  "El mismo texto para todos los leads; las variables se reemplazan con los datos de cada uno al enviar.": "O mesmo texto para todos os leads; as variáveis são substituídas pelos dados de cada um no envio.",
  "WhatsApp solo permite texto libre dentro de las 24 h siguientes a un mensaje del lead. Si no hay conversación abierta, este paso se omite.": "O WhatsApp só permite texto livre nas 24 h seguintes a uma mensagem do lead. Se não houver conversa aberta, esta etapa é ignorada.",
