  "No usó tu base de entrenamiento (vacía o sin nada relevante para este paso). Agrégala en Campañas → Entrenar la IA.": "Não usou sua base de treinamento (vazia ou sem nada relevante para esta etapa). Adicione conteúdo em Campanhas → Treinar a IA.",
  "Es una muestra: en la campaña cada lead recibe su propio mensaje, escrito 24 h antes del envío.": "É um exemplo: na campanha, cada lead recebe a própria mensagem, escrita 24 h antes do envio.",
  "Genera un mensaje real para el lead elegido y ajusta el ángulo o las instrucciones si no te convence. Cuesta 2 créditos.": "Gere uma mensagem real para o lead escolhido e ajuste o ângulo ou as instruções se não gostar. Custa 2 créditos.",
