  "Aplicar siempre": "Aplicar sempre",
  "La IA lo lee en todos los mensajes. Sin marcar, solo entra cuando es relevante para ese paso y ese lead.": "A IA o lê em todas as mensagens. Sem marcar, só entra quando é relevante para essa etapa e esse lead.",
  "Agregar a la base": "Adicionar à base",
  "Usar en los mensajes": "Usar nas mensagens",
  "La IA lo usa": "A IA usa",
  "Pausado: la IA no lo usa": "Pausado: a IA não usa",
  "se aplica siempre": "aplicado sempre",
  "Ver todo": "Ver tudo",
  "Todavía no le enseñaste nada a la IA": "Você ainda não ensinou nada à IA",
  "Hoy escribe con tu contexto de empresa y las tendencias generales. Empieza por lo que más cambia el resultado: tu metodología y 2 o 3 mensajes que ya te dieron respuestas.": "Hoje ela escreve com o contexto da sua empresa e as tendências gerais. Comece pelo que mais muda o resultado: sua metodologia e 2 ou 3 mensagens que já trouxeram respostas.",
  "Mensajes tuyos que obtuvieron respuesta": "Suas mensagens que tiveram resposta",
  "Los detectó el bucle de aprendizaje en tus campañas. Guárdalos como script para que la IA los tome como referencia de forma explícita.": "Detectadas pelo ciclo de aprendizado nas suas campanhas. Salve-as como script para que a IA as use como referência de forma explícita.",
  "Obtuvo respuesta en una campaña": "Teve resposta em uma campanha",
  "Guardar como script": "Salvar como script",
  "← Campañas": "← Campanhas",
  "Entrenar la IA": "Treinar a IA",
  "Sube tu metodología de venta, los scripts que ya te funcionaron y tu material. Antes de escribir cada mensaje de campaña, la IA busca aquí lo relevante para ese paso y ese lead y lo sigue por encima de las tendencias genéricas. Cada cambio aplica desde el próximo mensaje.": "Envie sua metodologia de vendas, os scripts que já funcionaram e seu material. Antes de escrever cada mensagem de campanha, a IA busca aqui o que é relevante para essa etapa e esse lead e segue isso acima das tendências genéricas. Cada mudança vale a partir da próxima mensagem.",
  "+ Agregar": "+ Adicionar",
  "Cargando tu base de entrenamiento…": "Carregando sua base de treinamento…",
  "Consejo: agrega tu framework de venta y márcalo \"Aplicar siempre\". Es lo que más ordena los mensajes.": "Dica: adicione seu framework de vendas e marque \"Aplicar sempre\". É o que mais organiza as mensagens.",
