  "Conecta tu CRM, tus automatizaciones y tu IA a Predictable": "Conecte seu CRM, suas automações e sua IA ao Predictable",
  "Igual que una app se conecta a HubSpot, tu CRM interno (o Zapier, Make, n8n, o un agente de IA) puede leer y escribir en Predictable: subir leads a tus listas, ponerlos en campañas, y enterarse al instante cuando alguien responde, agenda una reunión o aparece una señal de compra. Tu equipo técnico hace la conexión; tú solo creas la clave y les pasas el mensaje de abajo.": "Assim como um app se conecta ao HubSpot, seu CRM interno (ou Zapier, Make, n8n, ou um agente de IA) pode ler e gravar dados no Predictable: subir leads para suas listas, colocá-los em campanhas e saber na hora quando alguém responde, agenda uma reunião ou aparece um sinal de compra. Sua equipe técnica faz a conexão; você só cria a chave e passa para ela a mensagem abaixo.",
