  "Hola, sí me interesa. ¿Hablamos el jueves?": "Olá, tenho interesse sim. Podemos conversar na quinta?",
  "Autenticación": "Autenticação",
  "Cada request lleva la clave en la cabecera `Authorization: Bearer": "Cada requisição leva a chave no cabeçalho `Authorization: Bearer",
  "` (también se acepta `X-API-Key`). Las claves empiezan con `pai_live_`. **Permisos:** una clave de **solo lectura** puede consultar todo; una de **lectura y escritura** además crea, actualiza, enrola y borra. Usa la de menor permiso que tu integración necesite. Una clave revocada deja de funcionar al instante. La API responde siempre con los datos de la cuenta dueña de la clave: nunca ves ni tocas datos de otra cuenta.": "` (também é aceito `X-API-Key`). As chaves começam com `pai_live_`. **Permissões:** uma chave **somente leitura** pode consultar tudo; uma de **leitura e gravação** também cria, atualiza, inscreve e exclui. Use a de menor permissão de que sua integração precisa. Uma chave revogada para de funcionar na hora. A API sempre responde com os dados da conta dona da chave: você nunca vê nem altera dados de outra conta.",
  "Paginación y límites": "Paginação e limites",
  "Las listas devuelven `{ data, has_more, next_cursor }`. Para la página siguiente, repite la llamada con `?cursor=": "As listas retornam `{ data, has_more, next_cursor }`. Para a próxima página, repita a chamada com `?cursor=",
  "`. `limit` va de 1 a 200 (50 por defecto). **Sincronización incremental:** guarda la fecha de tu última sincronización y pide `GET /v1/contacts?updated_after=": "`. `limit` vai de 1 a 200 (50 por padrão). **Sincronização incremental:** guarde a data da sua última sincronização e peça `GET /v1/contacts?updated_after=",
  "`. **Límite de ritmo:** 120 requests por minuto por clave. Las cabeceras `X-RateLimit-Limit` y `X-RateLimit-Remaining` te dicen cuánto te queda; al pasarte recibes `429 rate_limited`: espera unos segundos y reintenta. **Lotes:** hasta 500 contactos por `POST /v1/contacts/bulk` y por enrolamiento; hasta 100 contactos por enriquecimiento.": "`. **Limite de taxa:** 120 requisições por minuto por chave. Os cabeçalhos `X-RateLimit-Limit` e `X-RateLimit-Remaining` informam quanto resta; ao ultrapassar, você recebe `429 rate_limited`: aguarde alguns segundos e tente novamente. **Lotes:** até 500 contatos por `POST /v1/contacts/bulk` e por inscrição; até 100 contatos por enriquecimento.",
  "Los errores devuelven el código HTTP correspondiente y `{ \"error\": { \"code\", \"message\", \"request_id\" } }`. El `message` está escrito para personas; decide con el `code`.": "Os erros retornam o código HTTP correspondente e `{ \"error\": { \"code\", \"message\", \"request_id\" } }`. A `message` é escrita para pessoas; decida com base no `code`.",
  "Falta un parámetro o no tiene el formato correcto.": "Falta um parâmetro ou ele não está no formato correto.",
  "La clave falta, no existe o fue revocada.": "A chave está ausente, não existe ou foi revogada.",
  "La clave es de solo lectura.": "A chave é somente leitura.",
  "El recurso no existe o no es de tu cuenta.": "O recurso não existe ou não é da sua conta.",
  "La operación choca con el estado actual.": "A operação conflita com o estado atual.",
  "Más de 120 requests por minuto.": "Mais de 120 requisições por minuto.",
  "Error nuestro: reintenta y, si se repite, escríbenos con el request_id.": "Erro nosso: tente novamente e, se persistir, escreva para nós com o request_id.",
  "Registra una URL **https** (en Desarrolladores → Webhooks o con `POST /v1/webhooks`) y Predictable le enviará un `POST` con cada evento que elijas. Responde con un código **2xx en menos de 10 segundos**; si no, reintentamos con espera creciente (1 min, 5 min, 30 min, 2 h, 6 h, 12 h, 24 h). Tras 50 fallos seguidos el webhook se desactiva y lo ves en la app. Cada envío lleva las cabeceras `Predictable-Event`, `Predictable-Delivery` (úsala para no procesar dos veces la misma entrega) y `Predictable-Signature: t=": "Registre uma URL **https** (em Desenvolvedores → Webhooks ou com `POST /v1/webhooks`) e o Predictable enviará um `POST` a ela com cada evento que você escolher. Responda com um código **2xx em menos de 10 segundos**; caso contrário, tentamos novamente com espera crescente (1 min, 5 min, 30 min, 2 h, 6 h, 12 h, 24 h). Após 50 falhas seguidas o webhook é desativado e você vê isso no app. Cada envio leva os cabeçalhos `Predictable-Event`, `Predictable-Delivery` (use-o para não processar duas vezes a mesma entrega) e `Predictable-Signature: t=",
  "`, donde la firma es `HMAC-SHA256(secreto, \"": "`, onde a assinatura é `HMAC-SHA256(segredo, \"",
  ".\")` en hexadecimal. **Verifica siempre la firma** antes de confiar en el contenido.": ".\")` em hexadecimal. **Sempre verifique a assinatura** antes de confiar no conteúdo.",
  "Si tu sistema no puede recibir webhooks, consulta `GET /v1/events?created_after=": "Se o seu sistema não puder receber webhooks, consulte `GET /v1/events?created_after=",
  "` cada pocos minutos: es la misma información (se guarda 30 días).": "` a cada poucos minutos: é a mesma informação (fica guardada por 30 dias).",
  "Predictable también es un servidor **MCP** (Model Context Protocol): conecta Claude, ChatGPT, Cursor o tu propio agente y podrá consultar y operar tu cuenta con las mismas herramientas y permisos que la API REST (una herramienta por operación: `contacts_list`, `contacts_bulk_upsert`, `campaigns_enroll`, `messages_list`…). Transporte: Streamable HTTP. Autenticación: la misma clave, en `Authorization: Bearer": "O Predictable também é um servidor **MCP** (Model Context Protocol): conecte Claude, ChatGPT, Cursor ou seu próprio agente e ele poderá consultar e operar sua conta com as mesmas ferramentas e permissões da API REST (uma ferramenta por operação: `contacts_list`, `contacts_bulk_upsert`, `campaigns_enroll`, `messages_list`…). Transporte: Streamable HTTP. Autenticação: a mesma chave, em `Authorization: Bearer",
