  "Conexión nativa por la API oficial de cada plataforma: tus listas llegan a tu CRM, a tus secuencias y a tus documentos sin exportar CSV. Tus credenciales se guardan en el servidor y nunca pasan por el navegador.": "Conexão nativa pela API oficial de cada plataforma: suas listas chegam ao seu CRM, às suas sequências e aos seus documentos sem exportar CSV. Suas credenciais ficam guardadas no servidor e nunca passam pelo navegador.",
