  "Todavía no hay nada entrenado para {0}: se usa el criterio general de Predictable con tu Contexto.": "Ainda não há nada treinado para {0}: é usado o critério geral do Predictable com o seu Contexto.",
  "Entrenado con: {0}": "Treinado com: {0}",
  "Máximo {0} metodologías: más marcos a la vez diluyen el consejo.": "Máximo de {0} metodologias: mais estruturas ao mesmo tempo diluem o conselho.",
  "Neuroventas": "Neurovendas",
  "Véndele a la mente, no a la gente": "Venda para a mente, não para as pessoas",
  "Primero el miedo y la seguridad, luego la emoción, al final los datos. Es la doctrina por defecto del coach.": "Primeiro o medo e a segurança, depois a emoção, por último os dados. É a doutrina padrão do coach.",
